let lang='tr', activeTab='today', selectedLevel='ALL', dailyGoal=10, listQuery='', listStatus='ALL', listLetter='ALL', pageNo=0, session=[], sessionIndex=0, isRevealed=false, isLoading=false, quiz=null, quizBusy=false, quizResult=null;
let shuffleMode=true, autoSpeak=false;
let state={};
const CACHE_KEY='lexipath3000_state_v1';

function todayKey(){
  const d=new Date();
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}

function shuffleArray(arr){
  const copy=[...arr];
  for(let i=copy.length-1;i>0;i--){
    const j=Math.floor(Math.random()*(i+1));
    [copy[i],copy[j]]=[copy[j],copy[i]];
  }
  return copy;
}

function loadState(){
  try{
    const x=JSON.parse(localStorage.getItem(CACHE_KEY)||'{}');
    state={
      known:x.known||{},
      saved:x.saved||{},
      meaningCache:x.meaningCache||{},
      today:x.today===todayKey()?x.today:todayKey(),
      todayDone:x.today===todayKey()?(x.todayDone||[]):[],
      streak:x.streak||0,
      lastStudy:x.lastStudy||'',
      goal:x.goal||10,
      shuffleMode:x.shuffleMode!==undefined?x.shuffleMode:true,
      autoSpeak:Boolean(x.autoSpeak)
    };
    dailyGoal=state.goal;
    shuffleMode=state.shuffleMode;
    autoSpeak=state.autoSpeak;
    if(!state.meaningCache)state.meaningCache={};
  }catch(e){
    state={known:{},saved:{},meaningCache:{},today:todayKey(),todayDone:[],streak:0,lastStudy:'',goal:10,shuffleMode:true,autoSpeak:false};
    dailyGoal=10;
  }
}

function saveState(){
  try{
    state.goal=dailyGoal;
    state.shuffleMode=shuffleMode;
    state.autoSpeak=autoSpeak;
    state.today=todayKey();
    localStorage.setItem(CACHE_KEY,JSON.stringify(state));
  }catch(e){}
}

function t(k){return (UI[lang]&&UI[lang][k])||UI.tr[k]||k}
function safe(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function levelMatch(w,l=selectedLevel){return l==='ALL'||(w.levels||[w.level]).includes(l)}
function statusOf(w){const k=String(w.id);if(state.known[k]==='known')return 'known';if(state.known[k]==='review')return 'review';return 'new'}
function byId(id){return WORDS[Number(id)]}
WORDS.forEach((w,i)=>w.id=i);

function countKnown(){return Object.values(state.known).filter(x=>x==='known').length}
function countReview(){return Object.values(state.known).filter(x=>x==='review').length}
function countSaved(){return Object.values(state.saved).filter(Boolean).length}
function countToday(){return (state.todayDone||[]).length}
function toast(msg){const root=document.getElementById('toastRoot');root.innerHTML=`<div class="toast">${safe(msg)}</div>`;setTimeout(()=>{root.innerHTML=''},2500)}

function updateSidebar(){
  document.getElementById('sideDone').textContent=countToday();
  document.getElementById('sideGoal').textContent=dailyGoal;
  document.getElementById('sideProgress').style.width=Math.min(100,countToday()/dailyGoal*100)+'%';
  document.getElementById('langToggle').textContent=lang==='tr'?'TR / EN':'EN / TR';
  document.querySelectorAll('[data-i]').forEach(n=>{let key=n.dataset.i;if(t(key))n.textContent=t(key)});
  document.getElementById('crumbCurrent').textContent=t(({today:'today',learn:'flashcards',list:'wordlist',quiz:'quickquiz',progress:'progress'})[activeTab]||'today');
  document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===activeTab));
}

function header(title,subtitle,kicker=''){return `<div class="page-title-row"><div><div class="eyebrow">${safe(kicker||'LEXIPATH 3000')}</div><h1>${safe(title)}</h1><p>${safe(subtitle)}</p></div></div>`}
function statCard(icon,label,value,foot){return `<div class="stat"><div class="stat-top"><span>${safe(label)}</span><span class="stat-symbol">${icon}</span></div><strong>${value}</strong><div class="stat-foot">${safe(foot)}</div></div>`}
function progressBar(pct){return `<div class="progress-track"><div class="progress-fill" style="width:${Math.max(0,Math.min(100,pct))}%"></div></div>`}

function getStudyPool(forceShuffle=shuffleMode){
  let pool=WORDS.filter(w=>levelMatch(w));
  let review=pool.filter(w=>statusOf(w)==='review');
  let fresh=pool.filter(w=>statusOf(w)==='new');
  let known=pool.filter(w=>statusOf(w)==='known');
  if(forceShuffle){
    review=shuffleArray(review);
    fresh=shuffleArray(fresh);
    known=shuffleArray(known);
  }
  return [...review,...fresh,...known];
}

function startSession(firstId){
  let pool=getStudyPool(shuffleMode);
  if(!pool.length)pool=shuffleMode?shuffleArray(WORDS):[...WORDS];
  if(firstId!==undefined){
    const first=byId(firstId);
    if(first){
      pool=pool.filter(w=>w.id!==first.id);
      pool.unshift(first);
    }
  }
  session=pool;
  sessionIndex=0;
  isRevealed=false;
  isLoading=false;
  activeTab='learn';
  render();
  if(autoSpeak&&session[0])speak(session[0].id);
}

function pickRandomWord(){
  if(!session.length)session=getStudyPool(true);
  if(session.length<=1)return;
  const currentId=curWord().id;
  // Öncelikle öğrenilmemiş kelimeler arasından rastgele seç
  let candidates=session.map((w,idx)=>({w,idx})).filter(item=>item.w.id!==currentId&&statusOf(item.w)!=='known');
  if(!candidates.length)candidates=session.map((w,idx)=>({w,idx})).filter(item=>item.w.id!==currentId);
  const picked=candidates[Math.floor(Math.random()*candidates.length)];
  sessionIndex=picked.idx;
  isRevealed=false;
  isLoading=false;
  render();
  if(autoSpeak)speak(curWord().id);
}

function curWord(){
  if(!session.length)session=getStudyPool(shuffleMode);
  return session[Math.max(0,Math.min(sessionIndex,session.length-1))]||WORDS[0];
}

async function fetchWordData(w){
  const key=String(w.word).toLowerCase();
  if(state.meaningCache[key]&&state.meaningCache[key].loaded)return state.meaningCache[key];
  let result={loaded:true,translation:'',definitions:[],examples:[],phonetic:''};
  const cleanQuery=w.word.replace(/\d+$/,'').replace(/\s*\(.*?\)\s*/g,'').trim();
  const enc=encodeURIComponent(cleanQuery.toLowerCase());
  const requests=[
    fetch('https://api.mymemory.translated.net/get?q='+encodeURIComponent(cleanQuery)+'&langpair=en%7Ctr')
      .then(r=>r.ok?r.json():Promise.reject())
      .then(j=>{if(j.responseStatus===200&&j.responseData&&j.responseData.translatedText)result.translation=cleanTranslation(j.responseData.translatedText)})
      .catch(()=>{}),
    fetch('https://api.dictionaryapi.dev/api/v2/entries/en/'+enc)
      .then(r=>r.ok?r.json():Promise.reject())
      .then(j=>{
        const entry=Array.isArray(j)?j[0]:null;
        if(entry){
          result.phonetic=entry.phonetic||(entry.phonetics||[]).find(p=>p.text)?.text||'';
          for(const m of entry.meanings||[]){
            for(const d of m.definitions||[]){
              if(d.definition&&result.definitions.length<2)result.definitions.push({pos:m.partOfSpeech,definition:d.definition});
              if(d.example&&result.examples.length<1)result.examples.push(d.example);
            }
          }
        }
      }).catch(()=>{})
  ];
  await Promise.all(requests);
  state.meaningCache[key]=result;
  saveState();
  return result;
}

function cleanTranslation(s){return String(s||'').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&amp;/g,'&').replace(/\s+/g,' ').trim()}

function drawWordReveal(w,data,mode='card'){
  const hasMeaning=Boolean(data&&(data.translation||data.definitions.length||data.examples.length));
  let html='';
  if(isLoading&&mode==='card')return `<div class="translation-area"><p class="translation">${safe(t('translationLoading'))}</p><p class="def">${safe(t('definitionLoading'))}</p></div>`;
  if(!hasMeaning)return `<div class="translation-area"><p class="def">${safe(t('noMeaning'))}</p><p class="def"><a style="color:#d4f3b3" target="_blank" rel="noopener" href="https://www.oxfordlearnersdictionaries.com/definition/american_english/${encodeURIComponent(w.word.toLowerCase().replace(/\s+/g,'_'))}">${safe(t('dictionaryLink'))}</a></p></div>`;
  if(data.translation)html+=`<p class="translation">${safe(data.translation)}</p>`;
  if(data.definitions.length)html+=data.definitions.map(d=>`<p class="def"><strong>${safe(d.pos||'')}</strong> ${safe(d.definition)}</p>`).join('');
  if(data.examples.length)html+=`<p class="example">“${safe(data.examples[0])}”</p>`;
  return `<div class="translation-area">${html}<div style="font-size:10px;color:#9fb6a5;margin-top:9px">${safe(t('translationSource'))}</div></div>`;
}

function renderToday(){
  const w=curWord();
  const st=statusOf(w), dat=state.meaningCache[String(w.word).toLowerCase()];
  const pct=Math.min(100,countToday()/dailyGoal*100);
  const topWords=WORDS.filter(x=>state.known[String(x.id)]==='review').slice(0,3);
  const saved=WORDS.filter(x=>state.saved[String(x.id)]).slice(0,3);
  const mini=topWords.length?topWords:saved.length?saved:session.slice(1,4);
  return `<div class="hello-row"><div><div class="eyebrow">${safe(t('todayDate'))}</div><h1>${safe(t('heroTitle'))}</h1><p>${safe(t('heroSub'))}</p></div><div class="day-chip">✦ ${new Date().toLocaleDateString(lang==='tr'?'tr-TR':'en-US',{weekday:'short',month:'short',day:'numeric'})}</div></div>
  <div class="stats">${statCard('▦',t('allWords'),WORDS.length.toLocaleString(),t('fromList'))}${statCard('✓',t('mastered'),countKnown().toLocaleString(),t('lifetime'))}${statCard('☆',t('saved'),countSaved().toLocaleString(),t('lifetime'))}${statCard('♨',t('streak'),state.streak+'',t('days'))}</div>
  <div class="dashboard-grid">
    <section class="panel">
      <div class="panel-head"><div><h2>${safe(t('todaySession'))}</h2><p>${safe(t('smartReview'))}</p></div><button class="section-link" data-action="go-tab" data-target="learn">${safe(t('continueLearning'))} →</button></div>
      <div class="learning-hero">
        <div class="word-card">
          <div class="word-card-top">
            <div style="display:flex;align-items:center;gap:9px"><span class="level-tag">${safe((w.levels||[w.level]).join(' / '))}</span><span class="pos-tag">${safe(w.pos)}</span></div>
            <div class="card-actions">
              <button class="icon-btn" title="${safe(t('pronunciation'))} (S)" data-action="speak" data-id="${w.id}">♫</button>
              <button class="icon-btn ${state.saved[String(w.id)]?'on':''}" title="${safe(t('save'))} (F)" data-action="save" data-id="${w.id}">☆</button>
            </div>
          </div>
          <div class="word-title">${safe(w.word)}</div>
          <p class="word-pron">${safe(dat?.phonetic||'American English')}</p>
          ${isRevealed?drawWordReveal(w,dat,'card'):`<p class="reveal-hint">${safe(t('reveal'))} — ${safe(t('tip1d'))}</p>`}
          <div class="card-bottom">
            <div class="button-row">
              ${isRevealed
                ?`<button class="btn btn-white" data-action="known" data-id="${w.id}">${safe(t('iKnow'))} ✓</button>
                  <button class="btn btn-outline" data-action="review" data-id="${w.id}">${safe(t('reviewAgain'))}</button>
                  <button class="btn btn-outline" data-action="hide-reveal">${safe(t('hideTranslation'))}</button>
                  <button class="btn btn-outline" data-action="random-card">↻ ${safe(t('randomCard'))}</button>`
                :`<button class="btn btn-primary" data-action="reveal">${safe(t('reveal'))} ↗</button>
                  <button class="btn btn-outline" data-action="random-card">↻ ${safe(t('randomCard'))}</button>
                  <button class="btn btn-outline" data-action="next">${safe(t('nextWord'))}</button>`}
            </div>
            <span class="card-index">${st==='known'?'✓ '+safe(t('statusKnown')):st==='review'?'↻ '+safe(t('statusLearning')):safe(t('statusNew'))}</span>
          </div>
        </div>
      </div>
    </section>
    <div class="dashboard-side">
      <section class="panel goal-panel">
        <div class="goal-head"><h2>${safe(t('goalTitle'))}</h2><span class="goal-icon">◎</span></div>
        <div class="goal-value"><strong>${countToday()}</strong><span>${safe(t('words'))} / ${dailyGoal}</span></div>
        ${progressBar(pct)}
        <p class="goal-note">${pct>=100?safe(t('goalReached')):`${Math.max(0,dailyGoal-countToday())} ${safe(t('toGoal'))}`}</p>
        <div class="eyebrow" style="margin-bottom:9px">${safe(t('setGoal'))}</div>
        <div class="goal-options">${[5,10,20].map(n=>`<button data-action="goal" data-value="${n}" class="${dailyGoal===n?'active':''}">${n} ${safe(t('words'))}</button>`).join('')}</div>
      </section>
      <section class="panel mini-panel">
        <div class="panel-head"><div><h2>${safe(t('quickAccess'))}</h2><p>${safe(t('reviewDue'))}</p></div><button class="section-link" data-action="go-tab" data-target="list">${safe(t('viewAll'))}</button></div>
        <div class="mini-list">${mini.length?mini.map(x=>`<div class="mini-word" style="cursor:pointer" data-action="study-id" data-id="${x.id}"><div class="letter-tile">${safe(x.word.slice(0,1).toUpperCase())}</div><div class="mini-word-main"><strong>${safe(x.word)}</strong><span>${safe((x.levels||[x.level]).join(' / '))} · ${safe(x.pos)}</span></div><span class="mini-status">${safe(statusLabel(statusOf(x)))}</span></div>`).join(''):`<div class="empty">${safe(t('noWords'))}</div>`}</div>
      </section>
    </div>
  </div>
  <section class="panel activity-panel"><div class="panel-head"><div><h2>${safe(t('studyTipTitle'))}</h2><p>${safe(t('learningPathD'))}</p></div></div><div class="activity-content"><div class="activity-item"><div class="activity-icon">↻</div><div><strong>${safe(t('tip1'))}</strong><p>${safe(t('tip1d'))}</p></div></div><div class="activity-item"><div class="activity-icon">◷</div><div><strong>${safe(t('tip2'))}</strong><p>${safe(t('tip2d'))}</p></div></div><div class="activity-item"><div class="activity-icon">♫</div><div><strong>${safe(t('tip3'))}</strong><p>${safe(t('tip3d'))}</p></div></div><div class="activity-item"><div class="activity-icon">⌨</div><div><strong>${safe(t('shortcuts'))}</strong><p>${safe(t('shortcutHint'))}</p></div></div></div></section>${footer()}`;
}

function statusLabel(s){return s==='known'?t('statusKnown'):s==='review'?t('statusLearning'):t('statusNew')}

function filteredWords(){
  let q=listQuery.trim().toLowerCase();
  return WORDS.filter(w=>{
    let match=(!q||w.word.toLowerCase().includes(q)||w.pos.toLowerCase().includes(q));
    let lev=levelMatch(w,selectedLevel);
    let st=listStatus==='ALL'||(listStatus==='SAVED'?state.saved[String(w.id)]:(statusOf(w)===listStatus.toLowerCase()));
    let firstChar=w.word.trim().charAt(0).toUpperCase();
    let letMatch=listLetter==='ALL'||firstChar===listLetter;
    return match&&lev&&st&&letMatch;
  });
}

