async function setReveal(){
  const w=curWord();
  isRevealed=true;
  isLoading=true;
  render();
  await fetchWordData(w);
  isLoading=false;
  render();
}

function markStatus(id,status){
  let k=String(id);
  if(status==='known'){
    state.known[k]='known';
    if(!state.todayDone.includes(k)){state.todayDone.push(k);recordStudyDay()}
    toast(t('knownToast'));
  }else{
    state.known[k]='review';
    toast(t('reviewToast'));
  }
  saveState();
  advanceCard();
  render();
}

function recordStudyDay(){
  let now=todayKey();
  if(state.lastStudy!==now){
    let last=state.lastStudy?new Date(state.lastStudy+'T00:00:00'):null;
    let today=new Date(now+'T00:00:00');
    if(last&&Math.round((today-last)/86400000)===1)state.streak=(state.streak||0)+1;
    else if(!last||state.lastStudy!==now)state.streak=1;
    state.lastStudy=now;
  }
}

function advanceCard(){
  if(!session.length)session=getStudyPool(shuffleMode);
  sessionIndex=(sessionIndex+1)%session.length;
  isRevealed=false;
  isLoading=false;
  if(autoSpeak&&session[sessionIndex])speak(session[sessionIndex].id);
}

function makeQuiz(){
  let pool=WORDS.filter(w=>levelMatch(w)&&statusOf(w)!=='known');
  if(pool.length<4)pool=WORDS.filter(w=>levelMatch(w));
  if(pool.length<4)pool=WORDS;
  let word=pool[Math.floor(Math.random()*pool.length)];
  const opts=[word];
  while(opts.length<4){
    const x=pool[Math.floor(Math.random()*pool.length)];
    if(!opts.some(o=>o.id===x.id))opts.push(x);
  }
  opts.sort(()=>Math.random()-.5);
  quiz={word,options:opts};
  quizResult=null;
  quizBusy=true;
  render();
  fetchWordData(word).then(()=>{quizBusy=false;render()});
}

function renderQuiz(){
  if(!quiz)makeQuiz();
  let w=quiz.word,dat=state.meaningCache[String(w.word).toLowerCase()];
  const prompt=dat?.translation||dat?.definitions?.[0]?.definition||t('checking');
  return `${header(t('quizTitle'),t('quizSub'),'RETRIEVAL PRACTICE')}
  <div class="quiz-wrap">
    <div class="goal-options" style="margin-bottom:14px">${['ALL','A1','A2','B1','B2'].map(l=>`<button data-action="quiz-level" data-value="${l}" class="${selectedLevel===l?'active':''}">${l==='ALL'?safe(t('allLevels')):l}</button>`).join('')}</div>
    <div class="quiz-shell">
      <div style="display:flex;justify-content:space-between;align-items:center;gap:10px">
        <span class="level-pill">${safe((w.levels||[w.level]).join(' / '))} · ${safe(w.pos)}</span>
        <span style="font-size:11px;color:#87938b">${safe(t('question'))}</span>
      </div>
      <div class="quiz-progress"><div style="width:${quizResult?100:35}%"></div></div>
      <div class="quiz-prompt-label">${safe(t('whichWord'))}</div>
      <div class="quiz-prompt">${quizBusy?safe(t('checking')):safe(prompt)}</div>
      <div class="quiz-options">${quiz.options.map((o,i)=>`<button class="quiz-option ${quizResult?(o.id===w.id?'correct':quizResult.chosen===o.id?'wrong':''):''}" data-action="answer" data-id="${o.id}" ${quizBusy||quizResult?'disabled':''}><span>${i+1}</span>${safe(o.word)}</button>`).join('')}</div>
      ${quizResult?`<div class="quiz-feedback">${quizResult.chosen===w.id?'✓ '+safe(t('correct')):'↻ '+safe(t('incorrect'))+' <strong>'+safe(w.word)+'</strong>'}${dat?.definitions?.[0]?.definition?'<br><span style="display:block;margin-top:5px">'+safe(dat.definitions[0].definition)+'</span>':''}</div>`:''}
      <div class="quiz-footer">
        <small>${safe(t('quizNote'))}</small>
        <div style="display:flex;gap:8px">
          ${quizResult?`<button class="btn btn-light" data-action="speak" data-id="${w.id}">♫</button><button class="btn btn-dark" data-action="next-quiz">${safe(t('nextQuestion'))}</button>`:`<button class="btn btn-quiet" data-action="next-quiz">↻ ${safe(t('randomCard'))}</button>`}
        </div>
      </div>
    </div>
  </div>${footer()}`;
}

function renderProgress(){
  const levels=['A1','A2','B1','B2'];
  const levelData=levels.map(l=>{
    const items=WORDS.filter(w=>(w.levels||[w.level]).includes(l));
    const known=items.filter(w=>statusOf(w)==='known').length;
    return {l,total:items.length,known,pct:Math.round(known/items.length*100)};
  });
  const total=WORDS.length,known=countKnown(),pct=Math.round(known/total*100);
  return `${header(t('progressTitle'),t('progressSub'),'YOUR LEARNING DASHBOARD')}
  <div class="progress-grid">
    <section class="panel progress-card"><h2>${safe(t('overall'))}</h2><p>${safe(t('overallCopy'))}</p><div class="big-progress"><div class="ring" style="--progress:${pct}%"><div class="ring-content"><strong>${pct}%</strong><span>${safe(t('overall'))}</span></div></div><div><strong style="font-size:23px">${known.toLocaleString()} / ${total.toLocaleString()}</strong><p>${safe(t('wordsKnown'))}</p><span class="level-pill">${total-known} ${safe(t('statusNew').toLowerCase())}</span></div></div>${progressBar(pct)}</section>
    <section class="panel progress-card"><h2>${safe(t('yourHabits'))}</h2><p>${safe(t('dailyProgress'))}</p><div class="mini-list" style="padding:0">${[[t('wordsKnown'),known,'✓'],[t('wordsSaved'),countSaved(),'☆'],[t('reviewCount'),countReview(),'↻'],[t('dailyDone'),countToday(),'◷']].map((r,i)=>`<div class="mini-word"><div class="letter-tile">${r[2]}</div><div class="mini-word-main"><strong>${safe(r[0])}</strong><span>${safe(i===3?t('todayDate'):t('lifetime'))}</span></div><strong>${r[1]}</strong></div>`).join('')}</div></section>
    <section class="panel progress-card" style="grid-column:1/-1"><h2>${safe(t('byLevel'))}</h2><p>${safe(t('byLevelSub'))}</p><div class="level-bar-list">${levelData.map(d=>`<div class="level-bar-item"><strong>${d.l}</strong>${progressBar(d.pct)}<small>${d.known} / ${d.total}</small></div>`).join('')}</div></section>
    <section class="panel progress-card" style="grid-column:1/-1"><h2>${safe(t('aboutTitle'))}</h2><p>${safe(t('aboutText'))}</p><p style="margin:0">${safe(t('disclaimer'))}</p><p style="margin-top:12px">${safe(t('offline'))}</p><button class="btn btn-quiet" data-action="reset" style="margin-top:10px">${safe(t('reset'))}</button></section>
  </div>${footer()}`;
}

function footer(){return `<div class="footer-note">${safe(t('offline'))}<br>${safe(t('disclaimer'))}<br>${safe(t('translationSource'))} · <a href="https://api.dictionaryapi.dev/" target="_blank" rel="noopener">Free Dictionary API</a></div>`}

function render(){
  updateSidebar();
  const main=document.getElementById('mainContent');
  if(activeTab==='today')main.innerHTML=renderToday();
  else if(activeTab==='learn')main.innerHTML=renderLearn();
  else if(activeTab==='list')main.innerHTML=renderList();
  else if(activeTab==='quiz')main.innerHTML=renderQuiz();
  else main.innerHTML=renderProgress();
}

function setTab(tab){
  activeTab=tab;
  document.getElementById('sidebar').classList.remove('open');
  if(tab==='learn'&&!session.length){session=getStudyPool(shuffleMode);sessionIndex=0;isRevealed=false}
  if(tab==='quiz'&&!quiz)makeQuiz();
  render();
}

function speak(id){
  const w=byId(id);
  if(!w)return;
  if(!('speechSynthesis'in window)){toast(t('loadError'));return}
  window.speechSynthesis.cancel();
  const cleanWord=w.word.replace(/\d+$/,'').replace(/\s*\(.*?\)\s*/g,'').trim();
  const u=new SpeechSynthesisUtterance(cleanWord);
  u.lang='en-US';
  u.rate=.88;
  window.speechSynthesis.speak(u);
}

function toggleSave(id){
  let k=String(id);
  if(state.saved[k]){delete state.saved[k];toast(t('wordUnsaved'))}
  else{state.saved[k]=true;toast(t('wordSaved'))}
  saveState();
  render();
}

function answerQuiz(id){
  if(quizBusy||quizResult)return;
  quizResult={chosen:Number(id)};
  if(Number(id)===quiz.word.id){
    state.known[String(quiz.word.id)]='known';
    if(!state.todayDone.includes(String(quiz.word.id))){state.todayDone.push(String(quiz.word.id));recordStudyDay()}
  }else state.known[String(quiz.word.id)]='review';
  saveState();
  render();
}

function setLevel(l){
  selectedLevel=l;
  pageNo=0;
  session=getStudyPool(shuffleMode);
  sessionIndex=0;
  isRevealed=false;
  render();
}

function handleAction(btn){
  const a=btn.dataset.action,id=btn.dataset.id;
  if(a==='menu'){document.getElementById('sidebar').classList.toggle('open');return}
  if(a==='toggle-lang'){lang=lang==='tr'?'en':'tr';render();return}
  if(a==='go-tab'){setTab(btn.dataset.target);return}
  if(a==='reveal'){setReveal();return}
  if(a==='hide-reveal'){isRevealed=false;render();return}
  if(a==='known'){markStatus(id,'known');return}
  if(a==='review'){markStatus(id,'review');return}
  if(a==='quick-known'){
    let k=String(id);
    if(state.known[k]==='known'){delete state.known[k]}
    else{state.known[k]='known';if(!state.todayDone.includes(k)){state.todayDone.push(k);recordStudyDay()}toast(t('knownToast'))}
    saveState();render();return;
  }
  if(a==='next'){advanceCard();render();return}
  if(a==='prev-card'){sessionIndex=(sessionIndex-1+session.length)%session.length;isRevealed=false;render();if(autoSpeak)speak(curWord().id);return}
  if(a==='study-id'){startSession(id);return}
  if(a==='save'){toggleSave(id);return}
  if(a==='speak'){speak(id);return}
  if(a==='goal'){dailyGoal=Number(btn.dataset.value);saveState();toast(t('goalSaved'));render();return}
  if(a==='level'){setLevel(btn.dataset.value);return}
  if(a==='quiz-level'){selectedLevel=btn.dataset.value;makeQuiz();return}
  if(a==='letter'){listLetter=btn.dataset.value;pageNo=0;render();return}
  if(a==='page'){pageNo+=Number(btn.dataset.dir);render();return}
  if(a==='answer'){answerQuiz(id);return}
  if(a==='next-quiz'){makeQuiz();return}
  if(a==='random-card'){pickRandomWord();return}
  if(a==='shuffle-deck'){session=getStudyPool(true);sessionIndex=0;isRevealed=false;toast(t('shuffledToast'));render();return}
  if(a==='toggle-order'){shuffleMode=!shuffleMode;saveState();session=getStudyPool(shuffleMode);sessionIndex=0;isRevealed=false;render();return}
  if(a==='toggle-autospeak'){autoSpeak=!autoSpeak;saveState();render();return}
  if(a==='reset'){
    if(confirm(t('resetConfirm'))){
      state.known={};state.saved={};state.todayDone=[];state.streak=0;state.lastStudy='';
      saveState();session=getStudyPool(shuffleMode);sessionIndex=0;toast(t('resetDone'));render();
    }
    return;
  }
}

document.addEventListener('click',e=>{
  const nav=e.target.closest('[data-tab]');
  if(nav){setTab(nav.dataset.tab);return}
  const b=e.target.closest('[data-action]');
  if(b){handleAction(b);return}
});

document.addEventListener('change',e=>{
  if(e.target.id==='levelSelect'){selectedLevel=e.target.value;pageNo=0;render()}
  if(e.target.id==='statusSelect'){listStatus=e.target.value;pageNo=0;render()}
});

document.addEventListener('input',e=>{
  if(e.target.id==='wordSearch'){
    const pos=e.target.selectionStart;
    listQuery=e.target.value;
    pageNo=0;
    const main=document.getElementById('mainContent');
    main.innerHTML=renderList();
    const input=document.getElementById('wordSearch');
    input.focus();
    input.setSelectionRange(pos,pos);
  }
});

document.addEventListener('keydown',e=>{
  if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;
  if(activeTab==='today'||activeTab==='learn'){
    const w=curWord();
    if(e.code==='Space'){e.preventDefault();isRevealed?(isRevealed=false,render()):setReveal();return}
    if(e.code==='ArrowRight'){e.preventDefault();advanceCard();render();return}
    if(e.code==='ArrowLeft'){e.preventDefault();sessionIndex=(sessionIndex-1+session.length)%session.length;isRevealed=false;render();return}
    if(e.key==='1'){e.preventDefault();markStatus(w.id,'known');return}
    if(e.key==='2'){e.preventDefault();markStatus(w.id,'review');return}
    if(e.key==='r'||e.key==='R'){e.preventDefault();pickRandomWord();return}
    if(e.key==='s'||e.key==='S'){e.preventDefault();speak(w.id);return}
    if(e.key==='f'||e.key==='F'){e.preventDefault();toggleSave(w.id);return}
  }else if(activeTab==='quiz'&&quiz){
    if(['1','2','3','4'].includes(e.key)&&!quizResult&&!quizBusy){
      const opt=quiz.options[Number(e.key)-1];
      if(opt)answerQuiz(opt.id);
    }else if((e.code==='Space'||e.code==='Enter')&&quizResult){
      e.preventDefault();
      makeQuiz();
    }
  }
});

loadState();
if(state.today!==todayKey()){state.today=todayKey();state.todayDone=[];saveState()}
session=getStudyPool(shuffleMode);
render();